/* =====================================================================
   ANIMATED LAB BENCH — one live scene per step of the practical lab: the oven heats, the burette
   drips, the flask changes colour at the end point, crystals grow, the hydrometer bobs, bubbles stream
   out of the capillary, precipitates fall. Every scene is drawn from the student's own sample, choices
   and mistakes (flags), so what is seen matches what is measured.
   ===================================================================== */
const BXC={glass:"#8fa3ad",metal:"#9aa7ae",dark:"#37474f",wood:"#c7a57a",red:"#e53935",water:"#cfe7f3"};
const bxNone=c=>(!c||c==="none")?BXC.water:c;
const bxLight=(c,t)=>tubeShade(bxNone(c),t);
let BXID=0;
function bxDefs(){return`<defs>
<linearGradient id="bxWall" x1="0" y1="0" x2="0" y2="1"><stop offset="0" style="stop-color:var(--surface)"/><stop offset="1" style="stop-color:var(--surface-2)"/></linearGradient>
<linearGradient id="bxTop" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#5d6d75"/><stop offset="1" stop-color="#3c4a51"/></linearGradient>
<linearGradient id="bxGl" x1="0" x2="1"><stop offset="0" stop-color="#fff" stop-opacity="0"/><stop offset=".15" stop-color="#fff" stop-opacity=".6"/><stop offset=".3" stop-color="#fff" stop-opacity="0"/><stop offset=".85" stop-color="#000" stop-opacity="0"/><stop offset="1" stop-color="#000" stop-opacity=".1"/></linearGradient>
<linearGradient id="bxMet" x1="0" x2="1"><stop offset="0" stop-color="#cfd8dc"/><stop offset=".5" stop-color="#eceff1"/><stop offset="1" stop-color="#90a4ae"/></linearGradient>
<radialGradient id="bxFl" cx=".5" cy=".8" r=".7"><stop offset="0" stop-color="#e3f2fd"/><stop offset=".35" stop-color="#42a5f5"/><stop offset=".75" stop-color="#ff9800" stop-opacity=".8"/><stop offset="1" stop-color="#ff5722" stop-opacity="0"/></radialGradient>
<radialGradient id="bxHot" cx=".5" cy=".5" r=".5"><stop offset="0" stop-color="#ff7043"/><stop offset="1" stop-color="#ff7043" stop-opacity="0"/></radialGradient>
</defs>`}
const BY=280; /* bench top */
function bxBench(){return`<rect x="0" y="0" width="600" height="${BY}" fill="url(#bxWall)"/><g opacity=".35">${Array.from({length:9},(_,i)=>`<line x1="${i*70+20}" y1="0" x2="${i*70+20}" y2="${BY}" stroke="var(--line)"/>`).join("")}</g><rect x="0" y="${BY}" width="600" height="50" fill="url(#bxTop)"/><rect x="0" y="${BY}" width="600" height="4" fill="#78909c"/>`}
const bxT=(x,y,t,o={})=>`<text x="${x}" y="${y}" text-anchor="${o.a||"middle"}" font-size="${o.s||12}" font-weight="${o.b?700:500}" fill="${o.c||"var(--ink)"}" style="font-family:var(--f-body)"${o.ltr?' direction="ltr"':""}>${t}</text>`;
const bxLbl=(x,y,t,o={})=>{const w=Math.max(40,String(t).replace(/<[^>]+>/g,"").length*6.4+16);return`<g><rect x="${x-w/2}" y="${y-13}" width="${w}" height="20" rx="10" fill="${o.bg||"var(--surface)"}" stroke="${o.st||"var(--line)"}"/>${bxT(x,y+1,t,{s:11.5,b:1,c:o.c||"var(--ink)"})}</g>`};
const bxClip=(d)=>{const id="bxc"+(++BXID);return[id,`<clipPath id="${id}"><path d="${d}"/></clipPath>`]};
/* ---------- liquid helper: colour may animate from c0 to c1 ---------- */
const bxFill=(c,c1,dur)=>c1&&c1!==c?`fill="${bxNone(c)}" class="bxcol" style="--c0:${bxNone(c)};--c1:${bxNone(c1)};animation-duration:${dur||3}s"`:`fill="${bxNone(c)}"`;
/* ---------- glassware ---------- */
function bxBeaker(cx,base,w,h,o={}){const x=cx-w/2,y=base-h;const d=`M${x} ${y} L${x} ${base-6} Q${x} ${base} ${x+6} ${base} L${x+w-6} ${base} Q${x+w} ${base} ${x+w} ${base-6} L${x+w} ${y} Z`;const [id,cp]=bxClip(d);const lv=base-h*(o.lvl??0.55);let inner="";
 if(o.lvl!==0)inner+=`<rect x="${x}" y="${lv}" width="${w}" height="${h}" ${bxFill(o.fill,o.fill1,o.dur)} opacity="${o.op||.85}"/><ellipse cx="${cx}" cy="${lv}" rx="${w/2}" ry="2.5" fill="#fff" opacity=".35"/>`;
 if(o.solid){const R=tubeRng("bk"+cx);const n=o.solid.n||26;for(let i=0;i<n;i++){const sx=x+6+R()*(w-12),sy=base-3-R()*(o.solid.h||10);inner+=`<circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="${(1.6+R()*2).toFixed(1)}" fill="${tubeShade(bxNone(o.solid.col),R()*.3-.15)}" ${o.solid.anim?`class="${o.solid.anim}" style="animation-delay:${(R()*1.5).toFixed(2)}s"`:""}/>`}}
 if(o.ppt){const R=tubeRng("pp"+cx);for(let i=0;i<40;i++){const sx=x+5+R()*(w-10),sy=base-2-R()*12;inner+=`<circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="${(1.3+R()*1.8).toFixed(1)}" fill="${tubeShade(bxNone(o.ppt),R()*.3-.15)}" class="bxfall" style="animation-delay:${(R()*1.8).toFixed(2)}s"/>`}}
 if(o.bubbles)for(let i=0;i<7;i++)inner+=`<circle cx="${(x+8+i*(w-16)/6).toFixed(1)}" cy="${base-6}" r="${1.6+(i%3)}" fill="#fff" opacity=".8" class="bxbub" style="--dy:${-(h*(o.lvl??.55)-8)}px;animation-delay:${(i*.27).toFixed(2)}s"/>`;
 if(o.cloud)inner+=`<rect x="${x}" y="${lv}" width="${w}" height="${h}" fill="${o.cloud}" opacity=".0" class="bxcloud"/>`;
 let out=`<g>${cp?`<defs>${cp}</defs>`:""}<g clip-path="url(#${id})">${inner}<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="url(#bxGl)"/></g><path d="M${x-3} ${y} L${x} ${y+2} L${x} ${base-6} Q${x} ${base} ${x+6} ${base} L${x+w-6} ${base} Q${x+w} ${base} ${x+w} ${base-6} L${x+w} ${y}" fill="none" stroke="${BXC.glass}" stroke-width="2"/>`;
 if(o.grad)for(let i=1;i<=4;i++){const gy=base-h*i/5;out+=`<line x1="${x+w-12}" y1="${gy}" x2="${x+w-3}" y2="${gy}" stroke="${BXC.glass}" stroke-width="1"/>`}
 if(o.steam)out+=bxSteam(cx,y-4,3);if(o.label)out+=bxT(cx,base-h/2+4,o.label,{s:10,c:"var(--muted)"});if(o.rod)out+=`<line x1="${cx-6}" y1="${y-26}" x2="${cx+8}" y2="${base-6}" stroke="#b0bec5" stroke-width="3" stroke-linecap="round" class="bxstir"/>`;
 return out+"</g>"}
function bxFlask(cx,base,s,o={}){const nw=9*s,bw=44*s,h=96*s,nh=34*s;const d=`M${cx-nw} ${base-h} L${cx-nw} ${base-h+nh} L${cx-bw} ${base-5} Q${cx-bw} ${base} ${cx-bw+6} ${base} L${cx+bw-6} ${base} Q${cx+bw} ${base} ${cx+bw} ${base-5} L${cx+nw} ${base-h+nh} L${cx+nw} ${base-h} Z`;const [id,cp]=bxClip(d);const lv=base-(h-nh)*(o.lvl??.4);let inner="";
 if(o.lvl!==0)inner+=`<rect x="${cx-bw}" y="${lv}" width="${bw*2}" height="${h}" ${bxFill(o.fill,o.fill1,o.dur)} opacity="${o.op||.85}"/>`;
 if(o.flash)inner+=`<circle cx="${cx}" cy="${lv+8}" r="${12*s}" fill="${o.flash}" class="bxflash"/>`;
 if(o.crystals){const R=tubeRng("fc"+cx);const n=o.small?70:26;for(let i=0;i<n;i++){const sx=cx-bw*0.8+R()*bw*1.6,sy=base-3-R()*(o.small?16:24);const sz=o.small?1.2+R()*1.2:2.5+R()*3.5;inner+=`<rect x="${sx.toFixed(1)}" y="${sy.toFixed(1)}" width="${sz.toFixed(1)}" height="${(sz*(1.2+R())).toFixed(1)}" transform="rotate(${(R()*80-40).toFixed(0)} ${sx.toFixed(1)} ${sy.toFixed(1)})" fill="${tubeShade(bxNone(o.crystals),R()*.3-.1)}" stroke="${tubeShade(bxNone(o.crystals),-.3)}" stroke-width=".4" class="bxgrow" style="animation-delay:${(R()*2.2).toFixed(2)}s"/>`}}
 if(o.ppt){const R=tubeRng("fp"+cx);for(let i=0;i<46;i++){const sx=cx-bw*0.85+R()*bw*1.7,sy=base-2-R()*12;inner+=`<circle cx="${sx.toFixed(1)}" cy="${sy.toFixed(1)}" r="${(1.3+R()*1.7).toFixed(1)}" fill="${tubeShade(bxNone(o.ppt),R()*.3-.15)}" class="bxfall" style="animation-delay:${(R()*2).toFixed(2)}s"/>`}}
 if(o.solid){const R=tubeRng("fs"+cx);for(let i=0;i<20;i++){inner+=`<circle cx="${(cx-bw*.5+R()*bw).toFixed(1)}" cy="${(base-3-R()*6).toFixed(1)}" r="${(1.5+R()*1.6).toFixed(1)}" fill="${tubeShade(bxNone(o.solid),R()*.2-.1)}" ${o.dissolve?`class="bxdiss" style="animation-delay:${(R()*1.5).toFixed(2)}s"`:""}/>`}}
 const sw=o.swirl?` class="bxswirl"`:"";
 return`<g${sw}><defs>${cp}</defs><g clip-path="url(#${id})">${inner}<rect x="${cx-bw}" y="${base-h}" width="${bw*2}" height="${h}" fill="url(#bxGl)"/></g><path d="${d}" fill="none" stroke="${BXC.glass}" stroke-width="2"/>${o.label?bxT(cx,base-14*s,o.label,{s:10,c:"var(--muted)"}):""}</g>`}
function bxCyl(cx,base,h,o={}){const w=o.w||40,x=cx-w/2,y=base-h;const d=`M${x} ${y} L${x} ${base-4} L${x+w} ${base-4} L${x+w} ${y} Z`;const [id,cp]=bxClip(d);const lv=base-4-(h-4)*(o.lvl??.75);
 let out=`<g><defs>${cp}</defs><rect x="${cx-w/2-10}" y="${base-5}" width="${w+20}" height="6" rx="2" fill="${BXC.glass}" opacity=".7"/><g clip-path="url(#${id})"><rect x="${x}" y="${lv}" width="${w}" height="${h}" ${bxFill(o.fill,o.fill1,o.dur)} opacity="${o.op||.85}"/>${o.pour?`<rect x="${x}" y="${lv}" width="${w}" height="${h}" fill="${bxNone(o.fill)}" opacity=".85" class="bxrise" style="transform-origin:${cx}px ${base}px"/>`:""}${o.bubbles?Array.from({length:6},(_,i)=>`<circle cx="${x+6+i*(w-12)/5}" cy="${base-10}" r="2" fill="#fff" opacity=".8" class="bxbub" style="--dy:${-(base-lv-14)}px;animation-delay:${i*.3}s"/>`).join(""):""}<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="url(#bxGl)"/></g><path d="M${x-3} ${y} L${x} ${y+2} L${x} ${base-4} M${x+w} ${base-4} L${x+w} ${y}" fill="none" stroke="${BXC.glass}" stroke-width="2"/>`;
 if(o.grad!==false)for(let i=1;i<10;i++)out+=`<line x1="${x}" y1="${base-4-(h-8)*i/10}" x2="${x+(i%5?6:11)}" y2="${base-4-(h-8)*i/10}" stroke="${BXC.glass}" stroke-width="1"/>`;
 return out+"</g>"}
function bxBurette(cx,top,h,o={}){const x=cx-6,bot=top+h;const lv=top+8+(h-16)*(o.lvl??.15);let g=`<rect x="${cx+28}" y="${top-20}" width="5" height="${BY-top+20}" fill="url(#bxMet)"/><rect x="${cx+6}" y="${top+30}" width="26" height="6" rx="2" fill="${BXC.dark}"/><rect x="${cx+6}" y="${top+h*0.62}" width="26" height="6" rx="2" fill="${BXC.dark}"/><ellipse cx="${cx+30}" cy="${BY}" rx="34" ry="5" fill="${BXC.dark}"/>`;
 const [id,cp]=bxClip(`M${x} ${top} L${x} ${bot} L${x+12} ${bot} L${x+12} ${top} Z`);
 g+=`<defs>${cp}</defs><g clip-path="url(#${id})"><rect x="${x}" y="${lv}" width="12" height="${h}" fill="${bxNone(o.fill)}" opacity=".8" ${o.drain?`class="bxdrain" style="--dl:${(o.drain*(h-16)).toFixed(0)}px"`:""}/><rect x="${x}" y="${top}" width="12" height="${h}" fill="url(#bxGl)"/></g><rect x="${x}" y="${top}" width="12" height="${h}" fill="none" stroke="${BXC.glass}" stroke-width="1.6"/>`;
 for(let i=0;i<=10;i++){const yy=top+8+(h-16)*i/10;g+=`<line x1="${x}" y1="${yy}" x2="${x+(i%5?4:8)}" y2="${yy}" stroke="${BXC.glass}" stroke-width="1"/>`}
 g+=`<path d="M${x+2} ${bot} L${cx-1} ${bot+18} L${cx+1} ${bot+18} L${x+10} ${bot}" fill="${bxNone(o.fill)}" opacity=".7" stroke="${BXC.glass}"/><rect x="${cx-11}" y="${bot+3}" width="22" height="6" rx="2" fill="#546e7a" ${o.drip?'class="bxtap2"':""}/>`;
 if(o.bubble)g+=`<circle cx="${cx}" cy="${bot+13}" r="2.6" fill="#fff" stroke="#90a4ae" stroke-width=".8" ${o.bubbleOut?'class="bxpop"':""}/>`;
 if(o.drip)for(let i=0;i<2;i++)g+=`<ellipse cx="${cx}" cy="${bot+22}" rx="2.2" ry="3" fill="${bxNone(o.fill)}" stroke="#90a4ae" stroke-width=".4" class="bxdrip" style="--dy:${o.dropTo||40}px;animation-delay:${i*.55}s;animation-duration:${o.fast?.45:1.1}s"/>`;
 if(o.eye)g+=bxEye(cx-30,lv);return g}
function bxEye(x,y){return`<g><ellipse cx="${x}" cy="${y}" rx="9" ry="5.5" fill="#fff" stroke="${BXC.dark}" stroke-width="1.4"/><circle cx="${x+2}" cy="${y}" r="2.6" fill="${BXC.dark}"/><line x1="${x+10}" y1="${y}" x2="${x+22}" y2="${y}" stroke="var(--teal)" stroke-dasharray="3 2" stroke-width="1.4"/></g>`}
function bxVolFlask(cx,base,o={}){const r=34,ny=base-2*r-6,nt=ny-74;const d=`M${cx-6} ${nt} L${cx-6} ${ny} A${r} ${r} 0 1 0 ${cx+6} ${ny} L${cx+6} ${nt} Z`;const [id,cp]=bxClip(d);const mark=nt+24;const lv=o.lvl==="over"?mark-6:o.lvl==="below"?mark+5:o.lvl==="mark"?mark:o.lvl==="half"?base-r-4:o.lvl==="empty"?base+10:mark+30;
 return`<g ${o.inv?'class="bxinv"':""}><defs>${cp}</defs><g clip-path="url(#${id})"><rect x="${cx-r}" y="${lv}" width="${2*r}" height="${base-lv+4}" ${bxFill(o.fill,o.fill1,o.dur)} opacity=".85"/><rect x="${cx-r}" y="${nt}" width="${2*r}" height="${base-nt}" fill="url(#bxGl)"/></g><path d="${d}" fill="none" stroke="${BXC.glass}" stroke-width="2"/><line x1="${cx-9}" y1="${mark}" x2="${cx+9}" y2="${mark}" stroke="${BXC.dark}" stroke-width="1.5"/>${o.stopper?`<rect x="${cx-8}" y="${nt-10}" width="16" height="11" rx="3" fill="#455a64"/>`:""}${bxT(cx,base-r-2,o.label||"",{s:10,c:"var(--muted)"})}</g>`}
function bxPipette(cx,top,o={}){const len=o.len||170;return`<g ${o.anim?`class="${o.anim}"`:""}><rect x="${cx-2.5}" y="${top}" width="5" height="${len*0.38}" fill="#fff" stroke="${BXC.glass}"/><ellipse cx="${cx}" cy="${top+len*0.5}" rx="10" ry="22" fill="${bxNone(o.fill)}" opacity=".75" stroke="${BXC.glass}" stroke-width="1.6"/><rect x="${cx-2.5}" y="${top+len*0.62}" width="5" height="${len*0.36}" fill="${bxNone(o.fill)}" opacity=".75" stroke="${BXC.glass}"/><line x1="${cx-6}" y1="${top+16}" x2="${cx+6}" y2="${top+16}" stroke="${BXC.dark}" stroke-width="1.4"/>${o.filler?`<rect x="${cx-9}" y="${top-26}" width="18" height="28" rx="6" fill="#ef5350"/>`:""}${o.drip?`<ellipse cx="${cx}" cy="${top+len}" rx="2" ry="3" fill="${bxNone(o.fill)}" class="bxdrip" style="--dy:${o.dropTo||30}px"/>`:""}</g>`}
function bxThermo(cx,top,h,o={}){const T=o.T??25,a=o.min??0,b=o.max??100;const fr=Math.max(0.02,Math.min(1,(T-a)/(b-a)));const colH=(h-16)*fr;return`<g><rect x="${cx-4}" y="${top}" width="8" height="${h}" rx="4" fill="#fff" stroke="${BXC.glass}"/><circle cx="${cx}" cy="${top+h+3}" r="6" fill="${BXC.red}"/><rect x="${cx-1.6}" y="${top+h-colH}" width="3.2" height="${colH+2}" fill="${BXC.red}" class="bxth" style="transform-origin:${cx}px ${top+h}px"/>${Array.from({length:6},(_,i)=>`<line x1="${cx+4}" y1="${top+8+(h-16)*i/5}" x2="${cx+8}" y2="${top+8+(h-16)*i/5}" stroke="${BXC.glass}"/>`).join("")}${o.lbl!==false?bxLbl(cx+(o.side||-44),top+20,`<tspan direction="ltr">${pF(T,o.dp??1)} °C</tspan>`,{c:"var(--danger)"}):""}</g>`}
function bxBalance(cx,o={}){const b=BY,w=170,x=cx-w/2;return`<g><rect x="${x}" y="${b-30}" width="${w}" height="30" rx="5" fill="#eceff1" stroke="#90a4ae"/><rect x="${x+10}" y="${b-25}" width="96" height="20" rx="3" fill="#1d2b22"/><text x="${x+102}" y="${b-10}" text-anchor="end" font-size="13" fill="#9cf2b4" style="font-family:var(--f-mono)" direction="ltr">${o.read??"0.0000"} g</text><circle cx="${x+w-20}" cy="${b-15}" r="5" fill="#90a4ae"/><rect x="${x+8}" y="${b-150}" width="${w-16}" height="120" rx="4" fill="#e3f2fd" opacity=".35" stroke="#90a4ae"/><line x1="${x+w/2}" y1="${b-150}" x2="${x+w/2}" y2="${b-30}" stroke="#90a4ae" stroke-dasharray="3 3"/><rect x="${cx-34}" y="${b-36}" width="68" height="5" rx="2" fill="url(#bxMet)"/>${o.obj||""}${bxT(cx,b-155,o.label||L("الميزان الحساس","Analytical balance"),{s:11,c:"var(--muted)"})}</g>`}
function bxWeighBottle(cx,base,o={}){return`<g ${o.anim?`class="${o.anim}"`:""}><rect x="${cx-13}" y="${base-30}" width="26" height="30" rx="3" fill="#e3f2fd" opacity=".6" stroke="${BXC.glass}" stroke-width="1.4"/><rect x="${cx-11}" y="${base-12}" width="22" height="11" fill="${bxNone(o.col||"#f7f7f4")}"/><rect x="${cx-15}" y="${base-36}" width="30" height="7" rx="2" fill="#cfd8dc" stroke="${BXC.glass}"/></g>`}
function bxPyc(cx,base,o={}){const r=24;const d=`M${cx-5} ${base-2*r-34} L${cx-5} ${base-2*r} A${r} ${r} 0 1 0 ${cx+5} ${base-2*r} L${cx+5} ${base-2*r-34} Z`;const [id,cp]=bxClip(d);const lv=o.lvl==="full"?base-2*r-34:o.lvl==="neck"?base-2*r-6:o.lvl==="empty"?base+5:base-2*r-34;
 let g=`<g><defs>${cp}</defs><g clip-path="url(#${id})"><rect x="${cx-r}" y="${lv}" width="${2*r}" height="${base-lv+4}" fill="${bxNone(o.fill)}" opacity="${o.lvl==="empty"?0:.85}" ${o.fillAnim?'class="bxrise" style="transform-origin:'+cx+'px '+base+'px"':""}/>${o.bubble?`<circle cx="${cx+8}" cy="${base-2*r+8}" r="5" fill="#fff" stroke="#90a4ae"/>`:""}<rect x="${cx-r}" y="${base-2*r-40}" width="${2*r}" height="${2*r+44}" fill="url(#bxGl)"/></g><path d="${d}" fill="none" stroke="${BXC.glass}" stroke-width="2"/>`;
 if(o.stopper!==false)g+=`<rect x="${cx-7}" y="${base-2*r-48}" width="14" height="16" rx="3" fill="#cfd8dc" stroke="${BXC.glass}"/><line x1="${cx}" y1="${base-2*r-48}" x2="${cx}" y2="${base-2*r-32}" stroke="#78909c"/>${o.overflow?`<ellipse cx="${cx}" cy="${base-2*r-50}" rx="2" ry="3" fill="${bxNone(o.fill)}" class="bxdrip" style="--dy:-0px"/>`:""}`;
 if(o.wet)g+=[[-12,-14],[9,-24],[-4,-34],[14,-8]].map(([a,b2],i)=>`<ellipse cx="${cx+a}" cy="${base+b2}" rx="2" ry="3" fill="#90caf9" class="bxdrop" style="animation-delay:${i*.3}s"/>`).join("");
 if(o.outside)g+=[[-26,-20],[25,-30]].map(([a,b2])=>`<ellipse cx="${cx+a}" cy="${base+b2}" rx="2.4" ry="3.4" fill="#90caf9"/>`).join("");
 return g+"</g>"}
function bxOven(cx,base,o={}){const w=170,h=140,x=cx-w/2,y=base-h;const on=o.on!==false;return`<g><rect x="${x}" y="${y}" width="${w}" height="${h}" rx="8" fill="#eceff1" stroke="#78909c" stroke-width="2"/><rect x="${x+12}" y="${y+12}" width="${w-56}" height="${h-24}" rx="5" fill="#263238"/><rect x="${x+12}" y="${y+12}" width="${w-56}" height="${h-24}" rx="5" fill="#ff7043" opacity="${on?.25:0}" ${on?'class="bxglow"':""}/>${[0,1,2].map(i=>`<path d="M${x+20} ${y+h-22-i*3} q8 -5 16 0 t16 0 t16 0 t16 0 t16 0" stroke="${on?"#ff5722":"#607d8b"}" stroke-width="2.4" fill="none" ${on?'class="bxglow"':""} style="animation-delay:${i*.2}s"/>`).join("")}<g transform="translate(${x+12+(w-56)/2},${y+h-26})">${o.inside||""}</g>${on?bxWaves(x+12+(w-56)/2,y+44):""}<rect x="${x+w-38}" y="${y+16}" width="28" height="16" rx="2" fill="#1d2b22"/><text x="${x+w-24}" y="${y+28}" text-anchor="middle" font-size="10" fill="#ff8a65" style="font-family:var(--f-mono)">${on?(o.T||110):"OFF"}</text><circle cx="${x+w-24}" cy="${y+52}" r="7" fill="#b0bec5" stroke="#78909c"/><circle cx="${x+w-24}" cy="${y+76}" r="4" fill="${on?"#e53935":"#90a4ae"}"/>${bxT(cx,y-8,L("فرن التجفيف","Drying oven"),{s:11,c:"var(--muted)"})}</g>`}
function bxWaves(cx,y){return`<g opacity=".7">${[-16,0,16].map((d,i)=>`<path d="M${cx+d} ${y+30} q5 -8 0 -16 q-5 -8 0 -16" stroke="#ffab91" stroke-width="1.6" fill="none" class="bxsteam" style="animation-delay:${i*.4}s"/>`).join("")}</g>`}
